log.raw:
{
  "critique": [
    {
      "design": "r0A",
      "good": "The metric names are recognizable, the numerical values and intervals stay on one line, and the paired control and variant columns have consistent proportions. Rows remain easy to follow.",
      "problems": "Only the control group and a sliver of the variant group appear in the initial viewport. The wide intervals create substantial horizontal travel before readers can compare the variant, lift, and p-value.",
      "cause": "The 134px and 131px confidence interval columns preserve entire ranges on one line, but they account for much of the 691px table width."
    },
    {
      "design": "r0B",
      "good": "The narrower interval columns bring the variant mean into the initial viewport and reduce scrolling. Most ranges wrap into readable endpoints, and corresponding groups remain similarly sized.",
      "problems": "The word 'abandonment' splits across lines, weakening the row label. The support-contact label takes four lines, and the time means wrap even though they are short values.",
      "cause": "The 120px metric column leaves 99px for text, just under the 100px longest word. The 71px and 70px mean columns leave too little room for the complete time values; the 90px interval columns deliberately trade single-line ranges for less scrolling."
    },
    {
      "design": "r0C",
      "good": "All seven columns are visible at once, so the group structure and the existence of lift and p-value can be seen without scrolling.",
      "problems": "Headers, metric names, numbers, and p-values fragment across lines. Rows become very tall, and readers must reconstruct values before they can compare them.",
      "cause": "Widths of 39–49px leave only 18–28px for most numeric cells, while the 100px metric column leaves 79px for labels. These widths are far below the space needed to keep the content intact."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "compact-readable",
      "widths": [121, 73, 90, 73, 90, 73, 76],
      "change": "Refine r0B by giving the longest metric word its full 100px of text space and restoring enough width for one-line means. Keep intervals at 90px so they can wrap while retaining the shorter scroll."
    },
    {
      "name": "roomier-labels",
      "widths": [150, 73, 90, 73, 90, 73, 76],
      "change": "Give metric names more room to improve their rhythm and reduce row height, while keeping the paired numeric columns consistent and allowing intervals to wrap."
    },
    {
      "name": "full-intervals",
      "widths": [150, 73, 134, 73, 131, 73, 76],
      "change": "Explore a wider, easier-to-scan table with more generous labels and complete intervals on one line. This costs additional horizontal scrolling but keeps each row's values together."
    }
  ]
}
